(() => {
  "use strict";

  const TEXTS = ["På morgonen äter Amir frukost innan skolan. Han tar på sig sin jacka och går till bussen. I väskan har han en bok, ett block och en penna.", "Efter skolan går Sara hem med sin kompis. De pratar om dagen och skrattar tillsammans. När Sara kommer hem gör hon en smörgås och börjar med läxan.", "Det regnar ute i dag. Leo tar på sig stövlar och en varm jacka. Han går till affären med sin pappa och hjälper till att bära en påse hem.", "Maja vaknar när väckarklockan ringer. Hon bäddar sängen, borstar tänderna och klär på sig. Sedan går hon till köket och äter frukost.", "På lördagen spelar Adam fotboll med sina vänner. Först värmer de upp och passar bollen. Efter matchen dricker de vatten och går hem.", "Nora går till biblioteket efter skolan. Hon hittar en bok om djur och sätter sig vid ett bord. Innan hon går hem lånar hon boken.", "I dag hjälper Elias sin mamma i köket. Han skär gurka och lägger maten på bordet. När allt är klart äter familjen middag tillsammans.", "Solen skiner när Lina går ut. Hon tar med en flaska vatten och går en promenad. På vägen ser hon en hund som leker i parken.", "På kvällen gör Samir sig redo för nästa dag. Han lägger fram kläder och packar sin skolväska. Sedan borstar han tänderna och går och lägger sig.", "Emma väntar på bussen utanför skolan. Bussen kommer efter några minuter. Hon sätter sig vid fönstret och åker hem.", "I klassrummet får eleverna en ny uppgift. Ali läser frågan två gånger och börjar skriva. När han är klar läser han igenom sitt svar.", "Mira går till affären för att köpa mjölk och bröd. Hon hittar varorna, betalar i kassan och lägger dem i en påse. Sedan går hon hem.", "Det är kallt ute på morgonen. Joel tar på sig mössa, vantar och jacka. Han går försiktigt eftersom marken är hal.", "Efter middagen hjälper Alma till hemma. Hon tar bort tallrikarna från bordet och ställer dem i diskmaskinen. Sedan torkar hon av bordet.", "Yara har glömt sin penna hemma. Hon frågar sin kompis om hon får låna en. Kompisen säger ja och Yara tackar för hjälpen.", "På rasten går Omar ut på skolgården. Han pratar med sina vänner och de spelar med en boll. När klockan ringer går de in igen.", "Hanna är törstig efter träningen. Hon fyller sin vattenflaska och sätter sig en stund. När hon har vilat går hon hem.", "Karim ska träffa sin vän klockan fyra. Han tittar på tiden och går hemifrån i god tid. De möts utanför butiken.", "I dag lär sig Sofia ett nytt svenskt ord. Hon läser ordet högt flera gånger och skriver det i en mening. Senare försöker hon använda ordet igen.", "David städar sitt rum på söndagen. Han lägger kläderna i garderoben och böckerna på hyllan. Till sist dammsuger han golvet.", "Efter skolan vill Amina vila en stund. Hon sätter sig i soffan och lyssnar på musik. Efter en liten paus börjar hon göra det hon behöver.", "I parken finns många träd och en liten lekplats. Noah går där med sin syster. De sätter sig på en bänk när de blir trötta.", "Fatima ska laga pasta till middag. Hon kokar vatten och lägger pastan i kastrullen. När maten är klar ropar hon att det är dags att äta.", "På väg till skolan ser Erik att en cykel har ramlat. Han ställer upp cykeln igen och fortsätter gå. Det tar bara några sekunder.", "Lina öppnar fönstret för att få in frisk luft. Sedan sätter hon sig vid skrivbordet och börjar läsa. Rummet känns lugnt och ljust.", "I dag har klassen idrott. Eleverna byter om och går till hallen. Läraren visar en övning och alla provar den i sin egen takt.", "Mariam får ett meddelande från sin vän. Vännen frågar om de ska ses efter skolan. Mariam svarar att det passar bra.", "Anton är hungrig när han kommer hem. Han tar ett äpple och ett glas vatten. Sedan sätter han sig vid bordet en stund.", "Det blåser mycket ute. Selma håller i sin mössa när hon går över gården. När hon kommer in hänger hon jackan på en krok.", "På kvällen tittar familjen på en film. De sitter tillsammans i soffan och har en filt över benen. Efter filmen pratar de om vad de tyckte.", "I skolan ska Benjamin arbeta med en kompis. De läser uppgiften och delar på arbetet. Till slut jämför de sina svar.", "Moa behöver köpa en present till sin vän. Hon går runt i några butiker och funderar. Till slut hittar hon något som passar.", "På morgonen hittar Isak inte sina nycklar. Han letar på bordet och i jackan. Till slut ser han dem bredvid sin väska.", "Ella tränar på att läsa svenska varje dag. Hon börjar med en kort text och läser långsamt. När ett ord är svårt provar hon en gång till.", "Ahmed går till tandläkaren på eftermiddagen. Han anmäler sig i receptionen och väntar på sin tur. Efter besöket går han hem.", "I dag ska Tilda baka med sin syster. De tar fram mjöl, ägg och socker. De följer receptet steg för steg och hjälps åt.", "På bussen ser Hassan en ledig plats. Han sätter sig och tar av sig ryggsäcken. När han närmar sig sin hållplats trycker han på stoppknappen.", "Julia får tillbaka ett prov i skolan. Hon tittar på sina svar och ser vad hon kan förbättra. Sedan frågar hon läraren om en sak.", "På söndagen ringer Elias till sin mormor. De pratar om veckan och vad de har gjort. Innan de lägger på bestämmer de att höras snart igen.", "Nadia ska tvätta sina kläder. Hon sorterar dem och lägger dem i tvättmaskinen. När tvätten är klar hänger hon upp kläderna.", "Victor har bråttom till skolan men stannar vid ett rödljus. Han väntar tills det blir grönt. Sedan går han över vägen.", "På lunchen väljer Maja ris, kyckling och grönsaker. Hon sätter sig med sina vänner. De äter och pratar innan nästa lektion.", "Oskar vill komma ihåg vad läraren säger. Han skriver några korta anteckningar i sitt block. Hemma läser han igenom dem igen.", "I dag är himlen grå men det regnar inte. Sara tar ändå med ett paraply i väskan. Hon vill vara redo om vädret ändras.", "Efter träningen känner sig Adam trött i benen. Han går hem, duschar och äter något. Sedan vilar han en stund.", "I korridoren tappar Leo några papper på golvet. En annan elev hjälper honom att plocka upp dem. Leo säger tack och ler.", "På morgonen kontrollerar Nora sin skolväska. Hon har med datorn, laddaren och sitt block. Sedan går hon ut genom dörren.", "I affären jämför Karim två olika varor. Han tittar på priset och hur mycket de innehåller. Sedan väljer han den som passar bäst.", "Alva vill lära sig ett nytt recept. Hon läser först hela receptet och tar fram allt hon behöver. Sedan börjar hon laga maten.", "När skoldagen är slut går Yasin till sitt skåp. Han tar sin jacka och lägger böckerna i väskan. Sedan möter han en vän utanför.", "På kvällen hörs regnet mot fönstret. Amir sitter vid bordet och ritar medan hans syster läser. Det är lugnt i rummet.", "Sofia ska skicka ett meddelande till sin lärare. Hon läser igenom texten innan hon skickar den. Hon vill att meddelandet ska vara tydligt.", "Efter frukosten fyller Omar sin vattenflaska. Han lägger den i ryggsäcken tillsammans med sina saker. Sedan går han till skolan.", "I dag ska eleverna läsa högt två och två. De turas om att läsa några meningar. Om någon fastnar hjälper de varandra.", "Samir tittar ut genom fönstret och ser att det snöar. Han tar på sig varma kläder innan han går ut. Marken är redan vit.", "Emma har en uppgift som känns svår. Hon börjar med den första delen och tar en sak i taget. Efter en stund känns uppgiften lättare.", "Efter middagen läser Lina några sidor i en bok. Hon hittar ett ord hon inte förstår och frågar vad det betyder. Sedan fortsätter hon läsa.", "Maja vill hålla ordning på sin vecka. Hon skriver ner några saker som hon behöver göra. Sedan väljer hon vad hon ska börja med.", "Nora lånar en penna men glömmer att lämna tillbaka den. När hon kommer på det går hon till sin vän och ger tillbaka pennan.", "I skolan ska Amina hålla en kort presentation. Hon tittar på sina stödord och pratar lugnt. När hon är klar känner hon sig nöjd."];
  const STORAGE_KEY = "mikal_skriva_text_history_v2";

  function norm(v) {
    return String(v || "").replace(/\s+/g, " ").trim();
  }

  function history() {
    try {
      const h = JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
      return Array.isArray(h) ? h.filter(Number.isInteger) : [];
    } catch {
      return [];
    }
  }

  function freshIndex() {
    const h = history();
    const blocked = new Set(h.slice(-12));
    let choices = TEXTS.map((_, i) => i).filter(i => !blocked.has(i));
    if (!choices.length) choices = TEXTS.map((_, i) => i);

    let index = choices[Math.floor(Math.random() * choices.length)];
    const last = h.length ? h[h.length - 1] : -1;

    if (index === last && choices.length > 1) {
      index = choices.find(i => i !== last);
    }

    h.push(index);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(h.slice(-14)));
    return index;
  }

  function findSource() {
    const selectors = [
      "#writingText", "#sourceText", "#textToCopy", "#copyText",
      "[data-writing-text]", ".writing-text", ".source-text",
      ".text-to-write", ".writing-source", ".copy-source"
    ];

    for (const s of selectors) {
      const el = document.querySelector(s);
      if (el && norm(el.textContent).length >= 20) return el;
    }

    const old = [...document.querySelectorAll("p,div,article")]
      .find(el =>
        norm(el.textContent).startsWith("I går gick Lina till biblioteket")
        && !el.querySelector("textarea,input,button")
      );

    if (old) return old;

    const label = [...document.querySelectorAll("p,div,span,h2,h3,h4")]
      .find(el => norm(el.textContent).toUpperCase() === "TEXT ATT SKRIVA");

    if (!label) return null;

    let box = label.parentElement;

    for (let level = 0; box && level < 5; level++, box = box.parentElement) {
      const labelTop = label.getBoundingClientRect().top;

      const candidates = [...box.querySelectorAll("p,div,span")]
        .filter(el => {
          if (el === label || el.contains(label)) return false;
          if (el.querySelector("textarea,input,button")) return false;

          const text = norm(el.textContent);
          if (text.length < 20 || text.length > 450) return false;

          const upper = text.toUpperCase();
          if (
            upper.includes("30 MINUTERS TRÄNING") ||
            upper.includes("LÄS OCH SKRIV SAMMA TEXT") ||
            upper.includes("SKRIV TEXTEN HÄR")
          ) return false;

          return el.getBoundingClientRect().top >= labelTop;
        })
        .sort((a, b) =>
          (a.childElementCount - b.childElementCount) ||
          (norm(a.textContent).length - norm(b.textContent).length)
        );

      if (candidates.length) return candidates[0];
    }

    return null;
  }

  function apply(index) {
    const el = findSource();
    if (!el) {
      console.warn("[Skriva V2] Kunde inte hitta texten att skriva av.");
      return false;
    }

    el.textContent = TEXTS[index];
    el.dataset.mikalWritingSource = "true";
    el.style.fontSize = "clamp(16px, 1.25vw, 18px)";
    el.style.lineHeight = "1.75";
    el.style.maxWidth = "74ch";
    return true;
  }

  function newText() {
    const i = freshIndex();
    apply(i);
    setTimeout(() => apply(i), 120);
    setTimeout(() => apply(i), 420);
  }

  function removeSidebar() {
    const marker = [...document.querySelectorAll("body *")]
      .find(el => norm(el.textContent).toUpperCase() === "SKRIVTRÄNING");

    if (!marker) return false;

    let node = marker;

    for (let level = 0; node && level < 6; level++, node = node.parentElement) {
      const t = norm(node.innerText || node.textContent).toUpperCase();

      if (
        t.includes("SKRIVTRÄNING") &&
        t.includes("KOPIERA TEXT") &&
        t.includes("LÄS OCH SKRIV AV") &&
        t.length < 280
      ) {
        const parent = node.parentElement;
        node.remove();

        if (parent) {
          parent.classList.add("mikal-writing-single-column");
          parent.style.display = "block";
          parent.style.gridTemplateColumns = "minmax(0,1fr)";

          [...parent.children].forEach(child => {
            child.style.width = "100%";
            child.style.maxWidth = "none";
            child.style.flex = "1 1 100%";
          });
        }

        return true;
      }
    }

    return false;
  }

  function addStyles() {
    if (document.getElementById("mikalSkrivaV2Styles")) return;

    const style = document.createElement("style");
    style.id = "mikalSkrivaV2Styles";
    style.textContent = `
      body.mikal-skriva-v2 .mikal-writing-single-column {
        width:100% !important;
        max-width:none !important;
        gap:0 !important;
      }

      body.mikal-skriva-v2 textarea {
        width:100% !important;
        max-width:100% !important;
        min-height:170px;
        font-size:clamp(16px,1.2vw,18px) !important;
        line-height:1.7 !important;
      }

      @media (max-width:1100px) {
        body.mikal-skriva-v2 .mikal-writing-single-column {
          display:block !important;
          grid-template-columns:minmax(0,1fr) !important;
        }

        body.mikal-skriva-v2 .mikal-writing-single-column > * {
          width:100% !important;
          max-width:none !important;
          margin-left:0 !important;
          margin-right:0 !important;
        }
      }

      @media (max-width:760px) {
        body.mikal-skriva-v2 [data-mikal-writing-source="true"] {
          font-size:16px !important;
          line-height:1.72 !important;
        }

        body.mikal-skriva-v2 textarea {
          min-height:150px !important;
          font-size:16px !important;
        }
      }
    `;

    document.head.appendChild(style);
  }

  function init() {
    document.body.classList.add("mikal-skriva-v2");
    addStyles();
    removeSidebar();
    newText();

    document.addEventListener("click", event => {
      const button = event.target.closest("button,a");
      if (!button) return;

      if (norm(button.textContent).toUpperCase().includes("NY TEXT")) {
        const i = freshIndex();
        setTimeout(() => apply(i), 50);
        setTimeout(() => apply(i), 180);
        setTimeout(() => apply(i), 420);
      }
    }, true);

    setTimeout(removeSidebar, 250);
    setTimeout(removeSidebar, 700);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, {once:true});
  } else {
    init();
  }
})();
